/* ---------- ölçüm kanıtı ---------- */
fresh();
T('ölçüm: referansın kendisi tolerans içinde', () => R(() => { const ref = allProfiles().find(p => p.ptype === 'psd'), tc = allTests()[0]; const m = mk('Measurement', tc.id, {ref:ref.id, pts:pfPts(ref)}); const r = measEval(m); delete M.els[m.id]; return r.ok && Math.abs(r.maxDev) < 1e-9 && Math.abs(r.grmsDev) < 1e-6; }));
T('ölçüm: +4 dB kayma tolerans dışı, Grms sapması yakalanır', () => R(() => { const ref = allProfiles().find(p => p.ptype === 'psd'), tc = allTests()[0]; const m = mk('Measurement', tc.id, {ref:ref.id, pts:pfPts(ref).map(q => [q[0], q[1] * Math.pow(10, 0.4)])}); const r = measEval(m); delete M.els[m.id]; return !r.ok && r.outPct > 99 && r.grmsDev > 50 && r.fails.length >= 2; }));
T('ölçüm: dar bantlı aşım izin yüzdesiyle kabul edilir', () => R(() => { const ref = allProfiles().find(p => p.ptype === 'psd'), rp = pfPts(ref), tc = allTests()[0]; const grid = logGrid(rp[0][0], rp[rp.length - 1][0], 100); const m = mk('Measurement', tc.id, {ref:ref.id, pts:grid.map(f => [f, pfAt(rp, f) * (f > 300 && f < 330 ? 3 : 1)]), grmsTol:50}); const r1 = measEval(m); m.allowOut = 5; const r2 = measEval(m); delete M.els[m.id]; return !r1.ok && r2.ok && r1.outPct > 0 && r1.outPct < 5; }));
T('ölçüm: termal profil ±°C', () => R(() => { const ref = allProfiles().find(p => p.ptype === 'thermal'); if(!ref) return true; const tc = allTests()[0]; const m = mk('Measurement', tc.id, {ref:ref.id, pts:pfPts(ref).map(q => [q[0], q[1] + 1])}); const r1 = measEval(m); m.tol = 0.5; const r2 = measEval(m); delete M.els[m.id]; return r1.ok && !r2.ok && r1.unit === '°C'; }));
T('ölçüm: örtüşmeyen aralık hata', () => R(() => { const ref = allProfiles().find(p => p.ptype === 'psd'), tc = allTests()[0]; const m = mk('Measurement', tc.id, {ref:ref.id, pts:[[5000, 1], [6000, 1]]}); const r = measEval(m); delete M.els[m.id]; return !!r.err; }));
T('ölçüm CSV: başlık, ondalık virgül, çoklu sütun', () => R(() => { const P = measParseRows([['Ölçüm dosyası'], ['Frekans (Hz)', 'X', 'Y'], ['20', '0,01', '0,011'], ['80', '0,04', '0,039'], ['2000', '0,007', '']]); return P.series.length === 2 && P.series[0].name === 'X' && P.series[0].pts[0][1] === 0.01 && P.series[1].pts.length === 2 && P.xName === 'Frekans (Hz)'; }));
