/* ---------- v1.44 gereksinim türetme ---------- */
fresh();
T('türetme: arayüz kuralı çıkış/giriş/standart önerir, metinler kalite denetiminden temiz geçer', () => R(() => { const L = deriveRun(['arayuz']); const bad = L.filter(s => reqQuality({text:s.text, reqId:'\u0000'}).length); return L.length === 6 && L.every(s => s.state === 'yeni' && /(acaktır|ecektir)\.$/.test(s.text)) && !bad.length || {n:L.length, bad:bad.map(s => s.text)}; }));
T('türetme: bütçe dağıtımı marjı ayırır, paylar sınırı aşmaz, adet başına', () => R(() => { const L = deriveRun(['butce']); const a = L.map(s => s.extra.budgetAlloc), tot = a.reduce((t, x) => t + x.val * x.mult, 0); const sb = L.find(s => /Sensör/.test(s.subsys)); return L.length === 3 && tot <= 45 * 0.9 + 1e-9 && tot > 40 && sb.extra.budgetAlloc.mult === 2 && /adet başına/.test(sb.text) && L.every(s => s.parent && E(s.parent).reqId === 'SYS-004') || {tot, n:L.length}; }));
T('türetme: eşit yöntem ve marj ayarı', () => R(() => { const r = allReqs().find(x => x.reqId === 'SYS-004'); deriveCfg().budget[r.id] = {method:'esit', margin:20}; const L = deriveRun(['butce']); const ok = L.every(s => Math.abs(s.extra.budgetAlloc.val * s.extra.budgetAlloc.mult - (s.extra.budgetAlloc.mult > 1 ? 2 : 1) * 0) >= 0) && L.map(s => s.extra.budgetAlloc.val * s.extra.budgetAlloc.mult).every(v => v <= 12 + 1e-9 && v > 11.9); delete deriveCfg().budget[r.id]; return ok || L.map(s => s.extra.budgetAlloc); }));
T('türetme: uygula → ilişkiler kurulur, tekrar çalıştırınca yinelenmez', () => R(() => { const L = deriveRun(['arayuz', 'butce']); const n0 = allReqs().length; const r = deriveApply(L.filter(s => s.state === 'yeni'), null); const L2 = deriveRun(['arayuz', 'butce']); const one = allReqs().find(x => x.derivedFrom && x.derivedFrom.sig.startsWith('bud:')); const sat = (relIdx().Satisfy || []).some(s => s.tgt === one.id), der = (relIdx().DeriveReqt || []).some(s => s.src === one.id); return r.n === 9 && allReqs().length === n0 + 9 && L2.every(s => s.state === 'mevcut') && sat && der && one.status === 'Taslak' && one.level === 'Alt Sistem' || {r, st:L2.map(s => s.state)}; }));
T('türetme: kaynak değişince "güncelle", onaylı gereksinim "Değişiklikte" olur', () => R(() => { const c = allConns().find(x => x.icdId === 'IF-001'); c.spec = '28 V DC, en çok 12 A'; bump(); const s = deriveRun(['arayuz']).find(x => x.sig.startsWith('if:' + c.id + ':out')); s.req.status = 'Onaylı'; deriveApply([s]); return s.state === 'güncelle' && /12 A/.test(s.req.text) && s.req.status === 'Değişiklikte' && deriveRun(['arayuz']).find(x => x.sig === s.sig).state === 'mevcut'; }));
T('türetme: elle düzenlenen metin korunur (mevcut sayılır)', () => R(() => { const s = deriveRun(['arayuz']).find(x => x.sig.includes(':in:')); s.req.text = 'Elle yazılmış metin.'; const s2 = deriveRun(['arayuz']).find(x => x.sig === s.sig); return s2.state === 'mevcut' && s2.edited === true && s.req.text === 'Elle yazılmış metin.'; }));
T('türetme: kaynak silinince "kaynak yok" → iptal; doğrulama uyarısı', () => R(() => { const c = allConns().find(x => x.icdId === 'IF-002'); const ids = deriveRun(['arayuz']).filter(s => s.sig.startsWith('if:' + c.id)).map(s => s.req.id); delModel([c.id]); afterChange(); const v = validateModel().some(x => x.rule === 'Türetme kaynağı silinmiş'); const L = deriveRun(['arayuz']).filter(s => s.state === 'kaynak yok'); deriveApply(L); return L.length === 3 && v && ids.every(id => E(id).status === 'İptal') || {n:L.length, v}; }));
T('türetme: bütçe payı aşımı ve tutarsız dağıtım doğrulamada çıkar', () => R(() => { const r = allReqs().find(x => x.budgetAlloc && /Güç/.test(x.subsys)); const keep = r.budgetAlloc.val; r.budgetAlloc.val = 1; const v1 = validateModel().some(x => x.rule === 'Bütçe payı aşıldı' && x.id === r.id); r.budgetAlloc.val = 40; const v2 = validateModel().some(x => x.rule === 'Bütçe dağıtımı tutarsız'); r.budgetAlloc.val = keep; return v1 && v2; }));
T('türetme: kabulden önce düzenlenen metin sonraki çalıştırmada "mevcut" kalır', () => { fresh(); return R(() => { const s = deriveRun(['butce'])[0]; deriveApply([Object.assign({}, s, {gen:s.text, text:'Elle düzeltilmiş bütçe metni olacaktır.'})]); const s2 = deriveRun(['butce']).find(x => x.sig === s.sig); return s2.state === 'mevcut' && s2.edited === true; }); });
T('benzerlik indeksi: ters indeks sonucu kaba kuvvet çift döngüyle aynı', () => { fresh(); return R(() => { const pk = mk('Package', M.rootId, {}); const W = ['sistem', 'kontrol', 'birimi', 'veri', 'besleme', 'gerilim', 'mesaj', 'durum', 'test', 'süre', 'hazır', 'çıkış']; let sd = 7; const rnd = () => (sd = (sd * 16807) % 2147483647) / 2147483647; for(let i = 0; i < 120; i++){ const n = 3 + Math.floor(rnd() * 4); mk('Requirement', pk.id, {text:Array.from({length:n}, () => W[Math.floor(rnd() * W.length)]).join(' ') + ' olacaktır'}); } qCache.sig = ''; const S = simIndex(); const rs = allReqs().filter(r => r.text && activeReq(r)), tok = rs.map(r => qTokens(r.text)); const B = new Map(); for(let i = 0; i < rs.length; i++) for(let j = i + 1; j < rs.length; j++){ const A = tok[i], C = tok[j]; if(A.size < 3 || C.size < 3) continue; let x = 0; A.forEach(w => { if(C.has(w)) x++; }); const jac = x / (A.size + C.size - x); if(jac >= 0.72){ [[i, j], [j, i]].forEach(([a, b]) => { const k = rs[a].id; if(!B.has(k)) B.set(k, []); B.get(k).push(rs[b].id + ':' + jac.toFixed(6)); }); } } const f = m => JSON.stringify([...m].map(([k, l]) => [k, l.slice(0, 3).map(x => typeof x === 'string' ? x : x[0].id + ':' + x[1].toFixed(6))]).sort()); const ok = f(S) === f(B) && B.size > 10; delModel([pk.id]); return ok || {a:S.size, b:B.size}; }); });
T('trNum / floorSig', () => R(() => trNum(16.6) === '16,6' && trNum(1234.4) === '1234' && trNum(25000) === '25.000' && floorSig(16.6666, 3) === 16.6 && floorSig(0.012349, 3) === 0.0123));

