T('çevre: uygula → üst gereksinimden Derive, profile Refine, mevcut teste Verify, test yoksa iskelet', () => R(() => { const L = deriveRun(['cevre']); const nT = allTests().length; deriveApply(L); const I = relIdx(); const q = L.find(s => /Kalifikasyon/.test(s.name)).req, sh = L.find(s => /SRS/.test(s.name)).req; const der = (I.DeriveReqt || []).some(x => x.src === q.id && E(x.tgt).reqId === 'SYS-005'); const ref = (I.Refine || []).some(x => x.tgt === q.id && E(x.src).kind === 'TestProfile'); const ver = (I.Verify || []).some(x => x.tgt === q.id && /kalifikasyon testi/i.test(E(x.src).name)); const tc = (I.Verify || []).filter(x => x.tgt === sh.id).map(x => E(x.src)); return der && ref && ver && allTests().length === nT + 1 && tc.length === 1 && tc[0].tLevel === 'Kalifikasyon' && (tc[0].profiles || []).length === 1 && deriveRun(['cevre']).every(s => s.state === 'mevcut') || {der, ref, ver, nt:allTests().length - nT}; }));
T('çevre: alt sistem seviyesinde her blok için ayrı, test iskeleti profil başına tek', () => { fresh(); return R(() => { deriveCfg().ruleOpts = {cevre:{sub:true}}; const L = deriveRun(['cevre']); const sh = L.filter(s => /SRS/.test(s.name)); const nT = allTests().length; deriveApply(sh); const ok = sh.length === 3 && sh.every(s => s.level === 'Alt Sistem') && allTests().length === nT + 1; deriveCfg().ruleOpts = {}; return ok || {n:sh.length, nt:allTests().length - nT}; }); });
T('doğrulama iskeleti: yöntem önerisi ve faaliyet oluşturma', () => { fresh(); return R(() => { const u0 = unverifiedReqs(); const r = u0.find(x => !x.verif) || u0[0]; const v0 = r.verif; const n = skeletonApply(u0.map(x => x.id)); const ok = n === u0.length && unverifiedReqs().length === 0 && String(r.verif).length > 0 && verifSuggest('Toplam kütle 40 kg olacaktır.') === 'Muayene' && verifSuggest('MTBF analizi ile gösterilecektir') === 'Analiz' && verifSuggest('Operatöre ekranda gösterecektir') === 'Gösterim' && verifSuggest('Sistem 28 V ile çalışacaktır') === 'Test'; return ok || {n, u:u0.length, left:unverifiedReqs().length, v0, v:r.verif}; }); });
