fresh();
T('fonksiyon: tahsisli aksiyon → blok, zaten karşılayanlar atlanır, kullanım durumları', () => R(() => { const L = deriveRun(['fonk']); const f = L.filter(s => s.sig.startsWith('fn:')), u = L.filter(s => s.sig.startsWith('uc:')); return f.length === 1 && f[0].text === 'Güç Birimi güç verecektir.' && f[0].level === 'Alt Sistem' && u.length === 3 && u.every(x => /Operatör için/.test(x.text)) && L.every(s => !reqQuality({text:s.text, reqId:'\u0000'}).length) || L.map(s => s.text); }));
T('fonksiyon: üst aktivitenin karşıladığı gereksinimden türetilir, Refine kurulur', () => R(() => { const s = deriveRun(['fonk']).find(x => x.sig.startsWith('fn:')); deriveApply([s]); const I = relIdx(); return E(s.parent).reqId === 'SYS-002' && (I.Refine || []).some(r => r.tgt === s.req.id && E(r.src).name === 'Güç ver') && (I.DeriveReqt || []).some(r => r.src === s.req.id); }));
T('mod/geçiş: olay, seçim düğümü (koşul + aksi), after(), başlangıç ve alt durum', () => R(() => { const L = deriveRun(['durum']); const tx = L.map(s => s.text).join('\n'); return L.length === 11 && /"Kapalı" durumundayken "güçVer" olayı alındığında "Kendi Kendine Test" durumuna geçecektir/.test(tx) && /\[bitSonuc == 1\] koşulu sağlanıyorsa "Hazır"/.test(tx) && /diğer koşullar sağlanmıyorsa "Arıza"/.test(tx) && /"Hazır" durumuna girdikten 30 s sonra "Kapalı"/.test(tx) && /başlangıçta "Kapalı" durumunda olacaktır/.test(tx) && /"Görevde" durumuna girdiğinde "Arama" alt durumunda başlayacaktır/.test(tx) && L.every(s => !reqQuality({text:s.text, reqId:'\u0000'}).length) || {n:L.length, tx}; }));
T('performans: P <= 120 bağlı değerle W birimli üst sınır; ters yazım ve karmaşık ifade', () => R(() => { const L = deriveRun(['kisit']); const ok1 = L.length === 1 && L[0].text === 'Güç Birimi güç değeri en fazla 120 W olacaktır.'; const cb = Object.values(M.els).find(e => e.kind === 'ConstraintBlock' && e.name === 'Güç Denklemi'); const keep = cb.expr; cb.expr = keep + '\n10 < V\nV * I >= 50'; bump(); const L2 = deriveRun(['kisit']); cb.expr = keep; bump(); const tx = L2.map(s => s.text).join('\n'); return ok1 && L2.length === 3 && /gerilim değeri 10 V değerinin üzerinde olacaktır/.test(tx) && /\[gerilim \* akım >= 50\] kısıtını sağlayacaktır/.test(tx) || tx; }));
T('performans: tolerans aralıklı değer', () => R(() => { const v = Object.values(M.els).find(e => e.kind === 'Value' && e.name === 'akım'); v.tol = {lo:3.2, hi:3.8, dist:'norm'}; bump(); const s = deriveRun(['kisit']).find(x => x.sig === 'tol:' + v.id); delete v.tol; bump(); return s && s.text === 'Güç Birimi akım değeri 3,2 A ile 3,8 A arasında olacaktır.'; }));
T('FMEA: RPN eşiği / şiddet, önlem metni, satıra bağlantı; risk seçeneği', () => R(() => { const L = deriveRun(['fmea']); const f = allFMs().find(x => x.name === 'Çıkış gerilimi yok'); const s = L.find(x => x.fmLink === f.id); const n0 = (f.reqs || []).length; deriveApply([s]); const linked = f.reqs.length === n0 + 1 && f.reqs.includes(s.req.id); deriveCfg().ruleOpts = {fmea:{risk:true}}; const L2 = deriveRun(['fmea']); deriveCfg().ruleOpts = {}; return L.every(x => (rpnOf(E(x.fmLink)) >= 100) || n10(E(x.fmLink).S) >= 9) && linked && /"Yedekli DC-DC, sigorta yerine PTC" önlemini sağlayacaktır/.test(s.text) && L2.some(x => x.riskLink && /riskine karşı/.test(x.text)) && !L.some(x => x.riskLink) || {n:L.length}; }));
T('varyant: kaynağın varyant koşulu öneriye ve gereksinime aktarılır', () => R(() => { const gv = Object.values(M.els).find(e => e.name === 'Güç ver'); gv.vcond = 'UzunMenzil'; bump(); const s = deriveRun(['fonk']).find(x => x.sig.startsWith('fn:' + gv.id)) || deriveRun(['fonk']).find(x => x.state === 'mevcut'); delete gv.vcond; bump(); return !!s && (s.state === 'mevcut' || s.vcond === 'UzunMenzil'); }));
