/* ---------- v1.47 kapsama, bölme, ARES ---------- */
fresh();
T('bölme: "ve" ile bağlı iki ister, virgüllü liste, iki cümle; tek isterli cümle bölünmez', () => R(() => { const a = splitReqText('Kontrol birimi durum mesajını 1 Hz ile yayınlayacak ve hata kodlarını kaydedecektir.'), b = splitReqText('Sistem, 28 V ile çalışacak, durumunu bildirecek ve arızaları raporlayacaktır.'), c = splitReqText('Güç birimi 5 V ve 12 V çıkış üretecektir.'); return JSON.stringify(a) === JSON.stringify(['Kontrol birimi durum mesajını 1 Hz ile yayınlayacaktır.', 'Kontrol birimi hata kodlarını kaydedecektir.']) && b.length === 3 && b[2] === 'Sistem, arızaları raporlayacaktır.' && c.length === 1 && splitReqText('A birimi X yapacaktır. A birimi Y yapacaktır.').length === 2 || {a, b, c}; }));
T('bölme: uygula → ilk parça özgünde, yeniler ilişkileri kopyalar, onaylı → Değişiklikte', () => R(() => { const r = allReqs().find(x => x.reqId === 'SUB-002'); r.text = 'Kontrol birimi açılışta kendi kendine testi 20 s içinde tamamlayacak ve sonucu kaydedecektir.'; r.status = 'Onaylı'; const I0 = relIdx(); const ver0 = (I0.Verify || []).filter(x => x.tgt === r.id).length, sat0 = (I0.Satisfy || []).filter(x => x.tgt === r.id).length, der0 = (I0.DeriveReqt || []).filter(x => x.src === r.id).length; const n = splitApply(r, splitReqText(r.text), true); const I = relIdx(), x = n[0]; return n.length === 1 && /tamamlayacaktır\.$/.test(r.text) && r.status === 'Değişiklikte' && x.level === r.level && x.subsys === r.subsys && x.splitFrom === r.id && (I.Verify || []).filter(v => v.tgt === x.id).length === ver0 && (I.Satisfy || []).filter(v => v.tgt === x.id).length === sat0 && (I.DeriveReqt || []).filter(v => v.src === x.id).length === der0 && ver0 + sat0 + der0 > 0 && !isMulti(r) && !isMulti(x) || {n:n.length, t:r.text}; }));
T('kapsama: kategori sınıflandırma (kural, alan, anahtar sözcük) ve blok eşleme', () => { fresh(); return R(() => { const c = t => [...reqCats({text:t})].join(','); const ok1 = c('Sistem MIL-STD-461G RE102 gerekliliklerini karşılayacaktır.') === 'emc' && c('Ünite MTBF değeri en az 5000 saat olacaktır.') === 'guv' && c('Toplam kütle en fazla 40 kg olacaktır.') === 'fiz' && c('Sistem açılıştan sonra 30 s içinde hazır olacaktır.') === 'perf' && [...reqCats({text:'x', category:'emc'})].includes('emc') && [...reqCats({text:'x', derivedFrom:{rule:'cevre'}})].includes('cevre'); const D = coverData(); const kb = D.rows.find(b => b.name === 'Kontrol Birimi'); return ok1 && D.rows.length === 4 && D.cell.get(kb.id + '|ara').length === 1 && D.cell.get(D.rows[0].id + '|fiz').length === 1; }); });
T('kapsama: türetilen gereksinimler boşlukları doldurur', () => R(() => { const D0 = coverData(), gap = (D, b, c) => !D.cell.get(b.id + '|' + c).length; const gb = D0.rows.find(b => b.name === 'Güç Birimi'); const g0 = gap(D0, gb, 'ara') && gap(D0, gb, 'guv'); deriveApply(deriveRun(['arayuz', 'fmea'])); const D1 = coverData(); return g0 && !gap(D1, gb, 'ara') && !gap(D1, gb, 'guv'); }));
T('ARES: bağlam paketi şeması ve içerik', () => { fresh(); return R(() => { const c = aresContext(); return c.schema === 'sysml-modeler/ares-context' && c.outputSchema.schema === 'ares/suggestions' && c.conventions.modalEnding === '-ecektir / -acaktır' && c.requirements.length === 10 && c.interfaces.length === 2 && c.interfaces[0].items.length > 0 && c.functions.some(f => f.allocatedTo.length) && c.stateMachines[0].transitions.length > 5 && c.environment.length === 5 && c.failureModes.length >= 3 && c.gaps.length > 10 && JSON.parse(JSON.stringify(c)).blocks.length > 3; }); });
T('ARES: içe aktarma → öneriler, üst gereksinim ve blok adla eşlenir, kabul ve yinelenmeme', () => R(() => { const out = {schema:'ares/suggestions', suggestions:[{level:'Alt Sistem', subsystem:'Güç Birimi', title:'Aşırı akım koruması', text:'Güç Birimi çıkış akımını 12 A değerinde sınırlayacaktır.', verification:'Test', parent:'SYS-001', satisfiedBy:'Güç Birimi', category:'emn', rationale:'FMEA', confidence:0.8}, {level:'Sistem', text:'Sistem MIL-STD-461G RE102 gerekliliklerini karşılayacaktır.', category:'emc'}, {text:''}]}; const P = aresImportText(JSON.stringify(out), 'ares.json'); const L = deriveRun(['ares']); const a = L.find(s => /12 A/.test(s.text)); deriveApply(L); const r = a.req; const I = relIdx(); const ok = P.items.length === 2 && P.errs.length === 1 && L.length === 2 && E(a.parent).reqId === 'SYS-001' && E(a.satisfyBy).name === 'Güç Birimi' && r.derivedFrom.rule === 'ares' && r.category === 'emn' && (I.Satisfy || []).some(x => x.tgt === r.id) && (I.DeriveReqt || []).some(x => x.src === r.id) && deriveRun(['ares']).every(s => s.state === 'mevcut'); let bad = false; try { aresParse('{"x":1}'); } catch(e){ bad = /suggestions/.test(e.message); } return ok && bad || {n:P.items.length, e:P.errs, L:L.length}; }));
T('karşılaştırma: kural ve ARES istatistikleri', () => R(() => { deriveList(); const S = deriveStats(); const ar = S.find(r => r.rule.id === 'ares'), ay = S.find(r => r.rule.id === 'arayuz'); return ar.acc === 2 && ar.sug >= 2 && ar.rate === 1 && ay.sug === 6 && ay.acc === 0 && ay.rate === 0 && S.length === DERIVE_RULES.length; }));

/* ---------- v1.49 kod sağlığı ---------- */
T('kancalar: durum, simülasyon çubuğu ve türetme kanca listeleri dolu; sarmalama yok', () => R(() => STATUS_HOOKS.length >= 2 && SIMBAR_HOOKS.length === 3 && DERIVE_HOOKS.apply.length >= 2 && DERIVE_HOOKS.run.length >= 1 && DERIVE_HOOKS.list.length >= 1));
T('türetme kabulü arayüzü bir kez yeniden çizer (afterChange tek çağrı)', () => { fresh(); return R(() => { let n = 0; const ac = afterChange; afterChange = function(){ n++; return ac.apply(this, arguments); }; const L = deriveRun(['cevre', 'fmea']); try { deriveApply(L, null, {mkTests:true}); } finally { afterChange = ac; } return n === 1 || n; }); });
T('relIdx önbelleği: ekleme/silmeden sonra güncel, aynı revizyonda aynı nesne', () => { fresh(); return R(() => { const a = relIdx(), b = relIdx(); const pk = mk('Package', M.rootId, {}), x = mk('Block', pk.id, {}), y = mk('Block', pk.id, {}); const r = addRel('Dependency', x.id, y.id); const c = relIdx(); delModel([pk.id]); const d = relIdx(); return a === b && c !== a && (c.Dependency || []).includes(r) && !(d.Dependency || []).includes(r); }); });

/* ---------- v1.51 akustik, SRS, AECTP, test prosedürü ---------- */
fresh();
T('akustik: OASPL = 1/3 oktav enerji toplamı; düz 100 dB, 10 bant → 110 dB', () => R(() => { const m = pfMetrics({ptype:'acoustic', pts:[[100, 100], [800, 100]]}); return m.ok && m.bands === 10 && Math.abs(m.oaspl - 110) < 0.01 && /110 dB OASPL/.test(m.main); }));
T('akustik: dB ara değer log-frekansta doğrusal; tolerans toplamsal', () => R(() => { const D = PT.acoustic; return Math.abs(pfAt([[100, 120], [400, 130]], 200, 'dB') - 125) < 1e-9 && pfTolHi(120, 3, D) === 123 && pfTolLo(120, 3, D) === 117 && pfDev(124, 120, D) === 4 && Math.abs(pfDev(2, 1, PT.psd) - 3.0103) < 1e-3; }));
T('akustik ölçüm: bant sapması ve OASPL sapması karara yazılır', () => R(() => { const p = mk('TestProfile', M.rootId, {name:'ak', ptype:'acoustic', pts:[[100, 130], [1000, 130]], tol:3, oaTol:1.5}); const tc = newTest({profiles:[p.id]}); const ok = mk('Measurement', tc.id, {ref:p.id, pts:thirdOct(100, 1000).map(f => [f, 131])}); const bad = mk('Measurement', tc.id, {ref:p.id, pts:thirdOct(100, 1000).map(f => [f, 132.5])}); const a = measEval(ok), b = measEval(bad); return a.ok && Math.abs(a.oaDev - 1) < 0.01 && !b.ok && b.outPct === 0 && b.fails.some(x => /OASPL/.test(x)); }));
T('SRS: uzun sinüs f0 → SRS(f0) ≈ Q·A; yüksek fn → A', () => R(() => { const fs = 20000, A = 2, f0 = 100, t = [], a = []; for(let i = 0; i < fs * 2; i++){ t.push(i / fs); a.push(A * Math.sin(2 * Math.PI * f0 * i / fs)); } const r = srsCalc(t, a, {Q:10, f0:100, f1:2000}); const at = f => r.pts.find(q => Math.abs(q[0] - f) / f < 0.01)[1]; return Math.abs(at(100.0) / (A * Math.sqrt(1 + 0.01) * 10) - 1) < 0.03 && Math.abs(at(2000) / A - 1) < 0.05 && r.pts.length === sixthOct(100, 2000).length; }));
T('SRS: yarım sinüs darbe — pozitif/negatif ayrımı, düşük örnekleme uyarısı', () => R(() => { const fs = 5000, t = [], a = []; for(let i = 0; i < 500; i++){ t.push(i / fs); a.push(i < 55 ? 50 * Math.sin(Math.PI * i / 55) : 0); } const r = srsCalc(t, a, {Q:10, f0:10, f1:2000}); const hi = r.pos[r.pos.length - 1][1], lo10 = r.pts[0][1]; return r.warn.some(w => /10 katından/.test(w)) && hi > 45 && hi < 60 && lo10 > 15 && lo10 < 25 && /* düşük frekans asimptotu ≈ 2π·f·Δv */ r.pts.every((q, i) => q[1] === Math.max(r.pos[i][1], r.neg[i][1])); }));
T('AECTP-400 şablonu: 3 gereksinim + taslak profil (Refine) + test; seviyeler TBD, çevre kuralı taslağı atlar', () => { fresh(); return R(() => { aectpApply(M.rootId, {ed:'', item:'X'}); const rs = allReqs().filter(r => /^AECTP-400 – /.test(r.name || '')), pf = allProfiles().filter(p => p.tbd); const ok = rs.length === 3 && rs.every(r => /\[TBD\]/.test(r.text) && /AECTP-400 Yöntem \[TBD\]/.test(r.text) && /(ecek|acak)tır\.$/.test(r.text) && envProfilesOf(r).length === 1) && pf.length === 3 && pf.some(p => p.ptype === 'acoustic'); const ids = new Set(rs.map(r => r.reqId)); return ok && ids.size === 3 && !deriveRun(['cevre']).some(s => pf.some(p => s.src.includes(p.id))) && pfMetrics(pf[0]).rows[0][0] === 'Durum' && validateModel().some(v => v.rule === 'Taslak test profili (TBD)'); }); });
T('test prosedürü taslağı: adımlar eksen başına, hazırlık/kabul doldurulur, dolu alan korunur', () => R(() => { const r = allReqs().find(x => /rastgele titreşim/.test(x.text || '') && envProfilesOf(x).some(p => p.tbd)); const tc = envTpDraft(r.id, true); const st = tcSteps(tc); const axes = st.filter(s => /^(X|Y|Z) ekseninde/.test(s.a)).length; const pre = tc.pre; tc.steps = [{a:'özel', exp:''}]; envTpDraft(r.id, true); return axes === 3 && /kalibrasyon/.test(pre) && /Ölçüm Değerlendirme kararı/.test(tc.accept) && tcSteps(tc).length === 1 && st[st.length - 1].exp === 'Ölçüm kararı: Geçti'; }));
T('çevre cümlesi: akustik profil OASPL ile', () => R(() => { const p = mk('TestProfile', M.rootId, {name:'Gürültü', ptype:'acoustic', pts:[[100, 100], [800, 100]], dur:'2'}); return envClause(p) === '100 Hz ile 800 Hz arasında 110 dB OASPL (ref 20 µPa) seviyesindeki "Gürültü" profiline 2 dk maruz kaldığında'; }));

